// <auto-generated/>
namespace Fanex.Tarus.Finance.Business.Transaction
{
    using System.Data;
    using Fanex.Tarus.Finance.Criteria;
    using Fanex.Tarus.Finance.Criteria.Transaction;
    using Fanex.Tarus.Finance.DataAccess.Transaction;
    using Fanex.Tarus.Finance.Entities;
    using Fanex.Tarus.Infrastructure.Extensions;

    public interface IFinanceCrossTransferService
    {
        ResultDataTable UpdateCrossMultiple(int userId, string fileName, int fileSize, string ip, string forexUsername);
    }

    public class FinanceCrossTransferService : IFinanceCrossTransferService
    {
        private readonly IFinanceTransferAccess financeTransferAccess;

        public FinanceCrossTransferService() : this(null)
        {
        }

        internal FinanceCrossTransferService(IFinanceTransferAccess financeTransferAccess)
            => this.financeTransferAccess = financeTransferAccess ?? new FinanceTransferAccess();

        public ResultDataTable UpdateCrossMultiple(int userId, string fileName, int fileSize, string ip, string forexUsername)
        {
            if (userId <= 0 || fileSize <= 0 || string.IsNullOrEmpty(fileName))
            {
                return new ResultDataTable(100, "Param input is invalid!");
            }

            var criteria = new FinanceCrossTransferMulUpdCriteria(userId, fileName, fileSize, ip, forexUsername);
            var customerCrossTransferList = financeTransferAccess.GetCustomerCrossTransferList(criteria);

            if (criteria.ErrCode != 0)
            {
                return new ResultDataTable(criteria.ErrCode, criteria.ErrMsg);
            }

            var success = CreateResultDataTable();
            var failure = CreateResultDataTable(true);

            foreach (var item in customerCrossTransferList)
            {
                var result = UpdateCrossMultiple(item);
                var dataTable = result.IsFailure ? failure : success;
                var drow = dataTable.NewRow();
                drow[0] = item.FromUsername;
                drow[1] = item.ToUsername;
                drow[2] = item.FromAmount;
                drow[3] = item.ToAmount;
                drow[4] = item.Remark;
                drow[5] = item.IsCollection;

                if (result.IsFailure)
                {
                    drow[6] = result.ErrorMessage;
                }

                dataTable.Rows.Add(drow);
            }

            WriteLog(userId, fileName, fileSize, ip, success.Rows.Count);

            return new ResultDataTable(0, string.Empty, success, failure);
        }

        private static DataTable CreateResultDataTable(bool isFailure = false)
        {
            var dataTable = new DataTable();
            dataTable.Columns.Add(new DataColumn("FromUserName", typeof(string)));
            dataTable.Columns.Add(new DataColumn("ToUserName", typeof(string)));
            dataTable.Columns.Add(new DataColumn("FromAmount", typeof(decimal)));
            dataTable.Columns.Add(new DataColumn("ToAmount", typeof(decimal)));
            dataTable.Columns.Add(new DataColumn("Description", typeof(string)));
            dataTable.Columns.Add(new DataColumn("IsCollection", typeof(bool)));

            if (isFailure)
            {
                dataTable.Columns.Add(new DataColumn("Reason", typeof(string)));
            }

            return dataTable;
        }

        private Result UpdateCrossMultiple(CustomerCrossTransfer param)
        {
            var fromSiteDB = ObjectDbExtensions.GetSiteDBConfigByCustId(param.FromCustId);
            var toSiteDB = ObjectDbExtensions.GetSiteDBConfigByCustId(param.ToCustId);
            var forexSiteDB = ObjectDbExtensions.GetSiteDBConfigByUsername(param.ForexUsername);

            if (fromSiteDB.SiteDBGroupID == toSiteDB.SiteDBGroupID
                && fromSiteDB.SiteDBGroupID == forexSiteDB.SiteDBGroupID)
            {
                return financeTransferAccess.ExecuteNonQuery(
                    new FinanceCrossTransferBettransInsCriteria(param, fromSiteDB),
                    fromSiteDB.AGIP);
            }

            // Step 1: transfer at SiteDB FROM
            var fromResult = financeTransferAccess.ExecuteNonQueryWithRefNo(
                new FinanceCrossTransferBettransInsSiteDBCriteria(param, fromSiteDB),
                fromSiteDB.AGIP);

            if (fromResult.IsFailure)
            {
                return fromResult;
            }

            ResultRefNo toResult = null;
            var refNo = fromResult.RefNo;
            // Step 2: transfer at SiteDB TO
            if (fromSiteDB.SiteDBGroupID != toSiteDB.SiteDBGroupID)
            {
                toResult = financeTransferAccess.ExecuteNonQueryWithRefNo(
                    new FinanceCrossTransferBettransInsSiteDBCriteria(param, toSiteDB, refNo),
                    toSiteDB.AGIP);

                if (toResult.IsFailure)
                {
                    // Rollback step 1
                    TransferRollbackSiteDB(refNo.Value, param.UserId, param.IP, fromSiteDB);

                    return toResult;
                }
            }

            // Step 3: transfer at SiteDB FOREX
            if (forexSiteDB.SiteDBGroupID != fromSiteDB.SiteDBGroupID
                && forexSiteDB.SiteDBGroupID != toSiteDB.SiteDBGroupID)
            {
                var forexResult = financeTransferAccess.ExecuteNonQueryWithRefNo(
                    new FinanceCrossTransferBettransInsSiteDBCriteria(param, forexSiteDB, refNo),
                    forexSiteDB.AGIP);

                if (forexResult.IsFailure)
                {
                    // Rollback step 1 & 2
                    TransferRollbackSiteDB(
                        refNo.Value,
                        param.UserId,
                        param.IP,
                        fromSiteDB,
                        toResult == null ? null : toSiteDB);
                }

                return forexResult;
            }

            return fromResult;
        }

        private void TransferRollbackSiteDB(
            long refNo,
            int userId,
            string ip,
            SiteDB fromSiteDB,
            SiteDB toSiteDB = null)
        {
            financeTransferAccess.ExecuteNonQuery(
                new TransferRollbackSiteDBCriteria(refNo, userId, ip, fromSiteDB),
                fromSiteDB.AGIP);

            if (toSiteDB != null)
            {
                financeTransferAccess.ExecuteNonQuery(
                    new TransferRollbackSiteDBCriteria(refNo, userId, ip, toSiteDB),
                    toSiteDB.AGIP);
            }
        }

        private Result WriteLog(int userId, string fileName, int fileSize, string ip, int totalUsers)
            => financeTransferAccess.ExecuteNonQuery(
                new FinanceCrossTransferMulUpdWrtieLogCriteria(userId, fileName, fileSize, ip, totalUsers));
    }
}
